import{_ as e,o,c as r,ax as a}from"./chunks/framework.Bnt0oLax.js";const g=JSON.parse(`{"title":"Getting Started","description":"Extend your community with Extensions (widgets, scripts, stylesheets), Connectors, and the SDK — or the No-Code Builder if you don't write code","frontmatter":{"description":"Extend your community with Extensions (widgets, scripts, stylesheets), Connectors, and the SDK — or the No-Code Builder if you don't write code"},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}`),s={name:"getting-started.md"};function n(i,t,d,l,c,h){return o(),r("div",null,[...t[0]||(t[0]=[a('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/getting-started.md for this page in Markdown format</div><h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Developer Studio lets you extend your community from code. You publish <strong>Extensions</strong> — widgets, scripts, and stylesheets — from a Git repository, wire them to external services with <strong>Connectors</strong>, and drive it all with the <strong>SDK</strong>. If you&#39;d rather not write code, the <strong>No-Code Builder</strong> lets you add and configure built-in widgets visually.</p><p>Whether you&#39;re a community manager enriching your pages or a developer building custom Extensions, this page points you to the right starting point.</p><h2 id="what-can-you-do" tabindex="-1">What Can You Do <a class="header-anchor" href="#what-can-you-do" aria-label="Permalink to &quot;What Can You Do&quot;">​</a></h2><p>There are several ways to extend your community, depending on your goals and technical comfort level.</p><h3 id="use-the-no-code-builder" tabindex="-1">Use the No-Code Builder <a class="header-anchor" href="#use-the-no-code-builder" aria-label="Permalink to &quot;Use the No-Code Builder&quot;">​</a></h3><p><strong>Best for</strong>: Community managers, content creators, anyone comfortable with drag-and-drop.</p><p>The <strong>No-Code Builder</strong> is a visual editor where you can add, arrange, and configure widgets on your community pages — no coding required. Many widgets are available out of the box.</p><h3 id="build-extensions-from-code" tabindex="-1">Build Extensions from Code <a class="header-anchor" href="#build-extensions-from-code" aria-label="Permalink to &quot;Build Extensions from Code&quot;">​</a></h3><p><strong>Best for</strong>: Developers who want full control over what they ship.</p><p><strong>Extensions</strong> are the widgets, scripts, and stylesheets you publish from a Git repository. Declare them in <code>extensions_registry.json</code>, push to your watched branch, and the platform publishes them automatically — with version control, code review, and branch-based environments.</p><ul><li><a href="/docs/custom-widgets/v2/">Extensions</a> — overview of widgets, scripts, and stylesheets</li><li><a href="/docs/custom-widgets/v2/build-first-widget.html">Your First Widget</a> — hands-on widget tutorial</li><li><a href="/docs/custom-widgets/v2/first-script.html">Your First Script</a> — hands-on script tutorial</li><li><a href="/docs/custom-widgets/v2/first-stylesheet.html">Your First Stylesheet</a> — hands-on stylesheet tutorial</li></ul><h3 id="connect-to-external-data" tabindex="-1">Connect to External Data <a class="header-anchor" href="#connect-to-external-data" aria-label="Permalink to &quot;Connect to External Data&quot;">​</a></h3><p><strong>Best for</strong>: Teams that want to pull or push data from services like Salesforce, Statuspage, or any API.</p><p><strong>Connectors</strong> act as secure bridges between your Extensions and external APIs. You configure them through a form-based interface — setting the URL, authentication, and data format — and your code can call them without exposing any credentials.</p><p><a href="/docs/connectors/">Connectors</a></p><h3 id="call-connectors-from-code" tabindex="-1">Call Connectors from Code <a class="header-anchor" href="#call-connectors-from-code" aria-label="Permalink to &quot;Call Connectors from Code&quot;">​</a></h3><p><strong>Best for</strong>: Developers wiring live data into a widget.</p><p>The <strong>SDK</strong> is the JavaScript library your widget code uses to call connectors and read community context from the browser.</p><p><a href="/docs/sdk/">SDK</a></p><h2 id="choose-your-path" tabindex="-1">Choose Your Path <a class="header-anchor" href="#choose-your-path" aria-label="Permalink to &quot;Choose Your Path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>I want to...</th><th>Start here</th></tr></thead><tbody><tr><td>Add widgets to pages without coding</td><td>Use the <strong>No-Code Builder</strong> (built into your community)</td></tr><tr><td>Build a custom widget from scratch</td><td><a href="/docs/custom-widgets/v2/build-first-widget.html">Your First Widget</a></td></tr><tr><td>Add a global script to the community</td><td><a href="/docs/custom-widgets/v2/first-script.html">Your First Script</a></td></tr><tr><td>Add a global stylesheet to the community</td><td><a href="/docs/custom-widgets/v2/first-stylesheet.html">Your First Stylesheet</a></td></tr><tr><td>Connect a widget to an external API</td><td><a href="/docs/connectors/build-first-connector.html">Build Your First Connector</a></td></tr><tr><td>Understand the SDK for calling connectors</td><td><a href="/docs/sdk/">SDK</a></td></tr><tr><td>Learn the key terms and concepts</td><td><a href="./getting-started/concepts.html">Key Concepts</a></td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/docs/custom-widgets/v2/build-first-widget.html">Your First Widget</a> — hands-on widget tutorial</li><li><a href="/docs/custom-widgets/v2/first-script.html">Your First Script</a> — hands-on script tutorial</li><li><a href="/docs/custom-widgets/v2/first-stylesheet.html">Your First Stylesheet</a> — hands-on stylesheet tutorial</li><li><a href="/docs/connectors/build-first-connector.html">Build Your First Connector</a> — hands-on tutorial for external API integration</li><li><a href="/docs/custom-widgets/v2/">Extensions</a> — all guides and reference for widgets, scripts, and stylesheets</li><li><a href="/docs/connectors/">Connectors</a> — all guides and reference for connectors</li><li><a href="./getting-started/concepts.html">Key Concepts</a> — the terms and ideas used throughout this documentation</li></ul>',25)])])}const m=e(s,[["render",n]]);export{g as __pageData,m as default};
